), aplicado AS (
  UPDATE service_occurrences o
     SET expected_deadline = n.deadline
    FROM nuevos n
   WHERE o.id = n.id
     AND o.expected_deadline > now()
     AND NOT EXISTS (
       SELECT 1 FROM compliance_facts cf WHERE cf.service_occurrence_id = o.id)
  RETURNING o.id
)
SELECT count(*) AS ocurrencias_corregidas FROM aplicado;

