  ('931ec2e3-2307-4d9b-9ceb-e5a268b8953b'::uuid, '2026-08-26T22:45:00.000Z'::timestamptz, '2026-08-27T00:30:00.000Z'::timestamptz)
), aplicado AS (
  UPDATE trips t
     SET evidence_window_start = n.inicio, evidence_window_end = n.fin
    FROM nuevas n
   WHERE t.id = n.id
     AND t.evidence_status = 'en_espera'
     AND NOT EXISTS (SELECT 1 FROM evidence_points ep WHERE ep.trip_id = t.id)
     AND NOT EXISTS (
       SELECT 1 FROM compliance_facts cf
        WHERE cf.service_occurrence_id = t.service_occurrence_id)
  RETURNING t.id
)
SELECT count(*) AS viajes_corregidos FROM aplicado;

-- 3 · Verificación: deadline y ventana tienen que quedar coherentes.
--     'descuadradas' debe ser 0. Si no lo es, ROLLBACK.
